changeSet.sql:
-- 1. branch CREATE TABLE branch ( id UUID PRIMARY KEY DEFAULT uuidv7(), name TEXT NOT NULL, address TEXT, phone TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), deleted_at TIMESTAMPTZ );
-- 2. role CREATE TABLE role ( id UUID PRIMARY KEY DEFAULT uuidv7(), name TEXT NOT NULL UNIQUE, description TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
-- 3. user CREATE TABLE "user" ( id UUID PRIMARY KEY DEFAULT uuidv7(), name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, google_sub TEXT, branch_id UUID REFERENCES branch(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), deleted_at TIMESTAMPTZ );
-- 4. user_role CREATE TABLE user_role ( user_id UUID NOT NULL REFERENCES "user"(id), role_id UUID NOT NULL REFERENCES role(id), assigned_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY (user_id, role_id) );
-- 5. payment_method CREATE TABLE payment_method ( id UUID PRIMARY KEY DEFAULT uuidv7(), branch_id UUID NOT NULL REFERENCES branch(id), name TEXT NOT NULL, active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
-- 6. customer CREATE TABLE customer ( id UUID PRIMARY KEY DEFAULT uuidv7(), branch_id UUID NOT NULL REFERENCES branch(id), name TEXT NOT NULL, phone TEXT, address TEXT, document TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), deleted_at TIMESTAMPTZ );
-- 7. book CREATE TABLE book ( id UUID PRIMARY KEY DEFAULT uuidv7(), branch_id UUID NOT NULL REFERENCES branch(id), title TEXT NOT NULL, author TEXT NOT NULL, isbn TEXT, publisher TEXT, publication_year INT, genre TEXT, category TEXT, condition TEXT NOT NULL, condition_notes TEXT, sale_price NUMERIC(10,2) NOT NULL, quantity INT NOT NULL DEFAULT 0, shelf_location TEXT, registered_at TIMESTAMPTZ NOT NULL DEFAULT now(), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), deleted_at TIMESTAMPTZ );
-- 8. book_image CREATE TABLE book_image ( id UUID PRIMARY KEY DEFAULT uuidv7(), book_id UUID NOT NULL REFERENCES book(id), url TEXT NOT NULL, sort_order SMALLINT NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
-- 9. book_price_history CREATE TABLE book_price_history ( id UUID PRIMARY KEY DEFAULT uuidv7(), book_id UUID NOT NULL REFERENCES book(id), changed_by UUID NOT NULL REFERENCES "user"(id), previous_price NUMERIC(10,2) NOT NULL, new_price NUMERIC(10,2) NOT NULL, changed_at TIMESTAMPTZ NOT NULL DEFAULT now() );
-- 10. discount CREATE TABLE discount ( id UUID PRIMARY KEY DEFAULT uuidv7(), branch_id UUID NOT NULL REFERENCES branch(id), created_by UUID NOT NULL REFERENCES "user"(id), name TEXT NOT NULL, scope TEXT NOT NULL, discount_type TEXT NOT NULL, value NUMERIC(10,2) NOT NULL, scope_book_id UUID, scope_category TEXT, scope_author TEXT, scope_price_min NUMERIC(10,2), scope_price_max NUMERIC(10,2), starts_at TIMESTAMPTZ, ends_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), deleted_at TIMESTAMPTZ );
-- 11. book_discount (UNIQUE on book_id enforces one active discount per book) CREATE TABLE book_discount ( id UUID PRIMARY KEY DEFAULT uuidv7(), book_id UUID NOT NULL UNIQUE REFERENCES book(id), discount_id UUID NOT NULL REFERENCES discount(id), applied_at TIMESTAMPTZ NOT NULL DEFAULT now() );
-- 12. voucher CREATE TABLE voucher ( id UUID PRIMARY KEY DEFAULT uuidv7(), branch_id UUID NOT NULL REFERENCES branch(id), customer_id UUID NOT NULL REFERENCES customer(id), issued_by UUID NOT NULL REFERENCES "user"(id), original_value NUMERIC(10,2) NOT NULL, balance NUMERIC(10,2) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
-- 13. sale CREATE TABLE sale ( id UUID PRIMARY KEY DEFAULT uuidv7(), branch_id UUID NOT NULL REFERENCES branch(id), cashier_id UUID NOT NULL REFERENCES "user"(id), voucher_id UUID REFERENCES voucher(id), total_amount NUMERIC(10,2) NOT NULL, voucher_amount NUMERIC(10,2), receipt_printed BOOLEAN NOT NULL DEFAULT false, sold_at TIMESTAMPTZ NOT NULL DEFAULT now(), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
-- 14. sale_item CREATE TABLE sale_item ( id UUID PRIMARY KEY DEFAULT uuidv7(), sale_id UUID NOT NULL REFERENCES sale(id), book_id UUID NOT NULL REFERENCES book(id), discount_id UUID REFERENCES discount(id), quantity INT NOT NULL, unit_price NUMERIC(10,2) NOT NULL, discounted_price NUMERIC(10,2), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
-- 15. sale_payment CREATE TABLE sale_payment ( id UUID PRIMARY KEY DEFAULT uuidv7(), sale_id UUID NOT NULL REFERENCES sale(id), payment_method_id UUID NOT NULL REFERENCES payment_method(id), amount NUMERIC(10,2) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
-- 16. used_book_purchase CREATE TABLE used_book_purchase ( id UUID PRIMARY KEY DEFAULT uuidv7(), branch_id UUID NOT NULL REFERENCES branch(id), manager_id UUID NOT NULL REFERENCES "user"(id), customer_id UUID REFERENCES customer(id), total_value NUMERIC(10,2) NOT NULL, payment_type TEXT NOT NULL, notes TEXT, purchased_at TIMESTAMPTZ NOT NULL DEFAULT now(), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
-- 17. used_book_purchase_item CREATE TABLE used_book_purchase_item ( id UUID PRIMARY KEY DEFAULT uuidv7(), purchase_id UUID NOT NULL REFERENCES used_book_purchase(id), book_id UUID NOT NULL REFERENCES book(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
-- 18. wishlist_item CREATE TABLE wishlist_item ( id UUID PRIMARY KEY DEFAULT uuidv7(), customer_id UUID NOT NULL REFERENCES customer(id), book_title TEXT NOT NULL, author TEXT, isbn TEXT, fulfilled BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
-- 19. notification CREATE TABLE notification ( id UUID PRIMARY KEY DEFAULT uuidv7(), branch_id UUID NOT NULL REFERENCES branch(id), user_id UUID NOT NULL REFERENCES "user"(id), type TEXT NOT NULL, title TEXT NOT NULL, body TEXT, read BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
-- 20. branch_shelf_config CREATE TABLE branch_shelf_config ( id UUID PRIMARY KEY DEFAULT uuidv7(), branch_id UUID NOT NULL UNIQUE REFERENCES branch(id), overdue_threshold_days INT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
-- 21. label_size (branch_id NULL = system default) CREATE TABLE label_size ( id UUID PRIMARY KEY DEFAULT uuidv7(), branch_id UUID REFERENCES branch(id), name TEXT NOT NULL, width_cm NUMERIC(5,2) NOT NULL, height_cm NUMERIC(5,2) NOT NULL, is_default BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
-- 22. voucher_redemption CREATE TABLE voucher_redemption ( id UUID PRIMARY KEY DEFAULT uuidv7(), voucher_id UUID NOT NULL REFERENCES voucher(id), sale_id UUID NOT NULL REFERENCES sale(id), amount_used NUMERIC(10,2) NOT NULL, redeemed_at TIMESTAMPTZ NOT NULL DEFAULT now(), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
